import { z } from 'zod'

import { MessageLimits } from './conversation-constants'
import { SettingsLimits } from './settings-constants'
import { canonicalTimezone } from './timezone'

export const uuidSchema = z.uuid()

// Generated by the client, one per message it means to send: the browser queue uses a UUID. The same
// shape is checked where the key is read from the request and where it travels back to the browsers.
export const idempotencyKeySchema = z
  .string()
  .max(MessageLimits.IDEMPOTENCY_KEY_MAX_LENGTH)
  .regex(/^[A-Za-z0-9_-]+$/, { message: 'letters, digits, hyphens and underscores only' })

// Zod runs every check even when the format already failed, so a text that is no link is not this
// check's to refuse (and `new URL` would throw on it)
function hasNoCredentials(link: string): boolean {
  if (!URL.canParse(link)) return true
  const { username, password } = new URL(link)
  return username === '' && password === ''
}

// A link that comes from outside (an ad's, a customer's) and may be drawn as a link or an image:
// only http and https, never `javascript:` or `data:`, and no user or password in it. Being well
// formed says nothing about where it points: whatever fetches it from a server (Step 3.4) must still
// refuse private addresses itself.
export const httpUrl = (maxLength: number): z.ZodURL =>
  z
    .url({ protocol: /^https?$/ })
    .max(maxLength)
    .refine(hasNoCredentials, { message: 'a link carries no credentials' })

// Control characters (line breaks included) and the invisible format ones (zero-width space, bidi
// overrides) make two names that look the same or draw a name backwards. The joiner U+200D stays: emoji
// are built with it.
const INVISIBLE = /[\p{Cc}\p{Cf}]/u
const JOINER = '‍'

// A name or a title: one visible line, in NFC so that "é" typed two ways is one name. Postgres text
// cannot hold a NUL character: it is a 400 here and not a 500 there.
export function singleLineText(
  maxLength: number,
  minLength = 0
): z.ZodPipe<z.ZodPipe<z.ZodString, z.ZodTransform<string, string>>, z.ZodString> {
  return z
    .string()
    .trim()
    .min(minLength)
    .max(maxLength)
    .transform(value => value.normalize('NFC'))
    .pipe(
      z.string().refine(value => !INVISIBLE.test(value.replaceAll(JOINER, '')), {
        message: 'contains a control or invisible character'
      })
    )
}

// A zone of the IANA database, stored in its canonical spelling
export const timezoneSchema = z
  .string()
  .max(SettingsLimits.TIMEZONE_MAX_LENGTH)
  .transform((value, ctx) => {
    const zone = canonicalTimezone(value)
    if (zone === null) ctx.addIssue({ code: 'custom', message: 'not a timezone' })
    return zone ?? z.NEVER
  })
